@prefix dt: <https://geolabs.github.io/bblocks-data-types/def/> .
@prefix rim: <https://w3id.org/ogc/rim/> .
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode dt:register ;
            sh:resultMessage "The data-types register must identify its one rim:ConceptSystem." ;
            sh:resultPath dt:conceptSystem ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraintComponent sh:MinCountConstraintComponent ;
            sh:sourceShape [ sh:class rim:ConceptSystem ;
                    sh:maxCount 1 ;
                    sh:message "The data-types register must identify its one rim:ConceptSystem." ;
                    sh:minCount 1 ;
                    sh:path dt:conceptSystem ] ] .

@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms true .
